  QuizQuestion(topic: "estequiometria", question: "Si el rendimiento teórico es 50 g y el real es 40 g, el rendimiento es:", options: ["125%", "80%", "20%", "90%"], answer: 1, explanation: "(40/50)×100 = 80%."),
