  QuizQuestion(topic: "estequiometria", question: "Masa molar del Al₂(SO₄)₃ (Al 26.98, S 32.06, O 16.00):", options: ["342.15 g/mol", "150.14 g/mol", "278.02 g/mol", "98.08 g/mol"], answer: 0, explanation: "2(26.98) + 3(32.06) + 12(16.00) = 53.96 + 96.18 + 192.00 = 342.14 g/mol."),
  QuizQuestion(topic: "estequiometria", question: "En una reacción, los coeficientes estequiométricos indican proporción en:", options: ["Gramos", "Moles", "Litros", "Átomos sueltos"], answer: 1, explanation: "Los coeficientes son proporciones en moles, nunca en gramos."),
  QuizQuestion(topic: "estequiometria", question: "¿Cuántos átomos de H hay en 1 mol de H₂SO₄?", options: ["6.022×10²³", "1.204×10²⁴", "2.409×10²⁴", "3.011×10²³"], answer: 1, explanation: "1 mol de H₂SO₄ tiene 2 mol de H: 2 × 6.022×10²³ = 1.204×10²⁴ átomos."),
  QuizQuestion(topic: "estequiometria", question: "Una muestra impura de 100 g tiene 80% de pureza. ¿Cuántos gramos puros hay?", options: ["20 g", "80 g", "100 g", "125 g"], answer: 1, explanation: "100 g × 0.80 = 80 g puros."),
  QuizQuestion(topic: "estequiometria", question: "¿Qué masa de CaCO₃ (M = 100.09 g/mol) necesitas para tener 0.50 mol?", options: ["25.0 g", "50.0 g", "100.1 g", "200.2 g"], answer: 1, explanation: "m = 0.50 × 100.09 ≈ 50.0 g."),
