  QuizQuestion(topic: "gases", question: "A TPN (0 °C, 1 atm), 2 mol de un gas ideal ocupan aproximadamente:", options: ["11.2 L", "22.4 L", "44.8 L", "48.8 L"], answer: 2, explanation: "El volumen molar a TPN es 22.41 L/mol; 2 mol × 22.41 ≈ 44.8 L."),
  QuizQuestion(topic: "gases", question: "En una mezcla con P total = 3 atm y fracción molar de N₂ = 0.80, la presión parcial del N₂ es:", options: ["0.80 atm", "2.40 atm", "3.00 atm", "3.75 atm"], answer: 1, explanation: "Ley de Dalton: P(N₂) = x·P total = 0.80 × 3 = 2.40 atm."),
  QuizQuestion(topic: "gases", question: "¿Qué volumen ocupa 1 mol de gas ideal a TPN?", options: ["1.0 L", "11.2 L", "22.4 L", "44.8 L"], answer: 2, explanation: "A 0 °C y 1 atm, 1 mol ocupa 22.41 L."),
  QuizQuestion(topic: "gases", question: "Si se duplica la presión de un gas a T constante, su volumen:", options: ["Se duplica", "Se reduce a la mitad", "No cambia", "Se cuadruplica"], answer: 1, explanation: "Ley de Boyle: P·V = constante, así que V se reduce a la mitad."),
  QuizQuestion(topic: "gases", question: "Convierte 27 °C a kelvin:", options: ["27 K", "273 K", "300 K", "310 K"], answer: 2, explanation: "K = °C + 273.15 ≈ 300 K."),
  QuizQuestion(topic: "gases", question: "En PV = nRT, ¿qué valor de R usas con P en atm y V en L?", options: ["8.314", "0.08206", "1.987", "0.0257"], answer: 1, explanation: "R = 0.08206 L·atm·mol⁻¹·K⁻¹ con esas unidades."),
  QuizQuestion(topic: "gases", question: "Un gas ocupa 4 L a 2 atm. A 4 atm (T constante) ocupará:", options: ["8 L", "4 L", "2 L", "1 L"], answer: 2, explanation: "Boyle: P₁V₁ = P₂V₂ → V₂ = (2×4)/4 = 2 L."),
  QuizQuestion(topic: "gases", question: "La presión total de una mezcla de gases es:", options: ["El promedio de las parciales", "La suma de las presiones parciales", "La mayor presión parcial", "La menor presión parcial"], answer: 1, explanation: "Ley de Dalton: P total = Σ Pᵢ."),
  QuizQuestion(topic: "gases", question: "¿Qué gas se difunde más rápido a igual T y P, H₂ o O₂?", options: ["O₂, por ser más pesado", "H₂, por ser más ligero", "Igual, la masa no importa", "Depende del volumen"], answer: 1, explanation: "Ley de Graham: la velocidad es inversamente proporcional a la raíz de la masa molar."),
  QuizQuestion(topic: "gases", question: "Si n se duplica a P y T constantes, el volumen:", options: ["Se duplica", "Se reduce a la mitad", "No cambia", "Se cuadruplica"], answer: 0, explanation: "Ley de Avogadro: V ∝ n."),
  QuizQuestion(topic: "gases", question: "La densidad de un gas a P y T fijas es proporcional a:", options: ["Su masa molar", "Su volumen", "Su temperatura", "1 / masa molar"], answer: 0, explanation: "d = P·M / (R·T): a P y T fijas, d ∝ M."),
  QuizQuestion(topic: "gases", question: "¿Cuántos moles hay en 11.2 L de un gas ideal a TPN?", options: ["0.25 mol", "0.50 mol", "1.00 mol", "2.00 mol"], answer: 1, explanation: "11.2 L ÷ 22.41 L/mol ≈ 0.50 mol."),
  QuizQuestion(topic: "disoluciones", question: "Disuelves 0.10 mol de glucosa y aforas a 500 mL. La molaridad es:", options: ["0.050 M", "0.10 M", "0.20 M", "0.50 M"], answer: 2, explanation: "M = n/V = 0.10 mol ÷ 0.500 L = 0.20 M."),
  QuizQuestion(topic: "disoluciones", question: "Para preparar 200 mL de HCl 0.50 M desde HCl 2.0 M, necesitas de la concentrada:", options: ["25 mL", "50 mL", "100 mL", "400 mL"], answer: 1, explanation: "M₁V₁ = M₂V₂ → V₁ = (0.50 × 200) / 2.0 = 50 mL."),
  QuizQuestion(topic: "disoluciones", question: "La molalidad se define como moles de soluto por:", options: ["Litro de disolución", "Litro de disolvente", "Kg de disolución", "Kg de disolvente"], answer: 3, explanation: "Molalidad = mol soluto / kg DISOLVENTE. Por eso no depende de la temperatura."),
  QuizQuestion(topic: "disoluciones", question: "Al diluir una disolución al doble de volumen, los moles de soluto:", options: ["Se duplican", "Se reducen a la mitad", "No cambian", "Dependen del soluto"], answer: 2, explanation: "Diluir solo añade disolvente: los moles de soluto se conservan (de ahí M₁V₁ = M₂V₂)."),
  QuizQuestion(topic: "disoluciones", question: "¿Qué es la molaridad?", options: ["Mol de soluto por kg de disolvente", "Mol de soluto por litro de disolución", "Gramos por litro", "Mol por mol de disolvente"], answer: 1, explanation: "M = n soluto / V disolución en litros."),
  QuizQuestion(topic: "disoluciones", question: "Tienes 0.20 mol en 0.40 L. La molaridad es:", options: ["0.20 M", "0.40 M", "0.50 M", "0.80 M"], answer: 2, explanation: "M = 0.20 ÷ 0.40 = 0.50 M."),
  QuizQuestion(topic: "disoluciones", question: "Al diluir al doble de volumen, la concentración:", options: ["Se duplica", "Se reduce a la mitad", "No cambia", "Se cuadruplica"], answer: 1, explanation: "M₂ = M₁·V₁/V₂: si V₂ = 2V₁, M₂ = M₁/2."),
  QuizQuestion(topic: "disoluciones", question: "Para preparar 1 L de NaCl 1.0 M necesitas:", options: ["1 mol de NaCl", "1 g de NaCl", "58.44 mol de NaCl", "0.1 mol de NaCl"], answer: 0, explanation: "M = n/V → n = 1.0 × 1 = 1 mol."),
  QuizQuestion(topic: "disoluciones", question: "El % en masa de 10 g de sal en 90 g de agua es:", options: ["9%", "10%", "11%", "20%"], answer: 1, explanation: "Masa total = 100 g; (10/100)×100 = 10%."),
  QuizQuestion(topic: "disoluciones", question: "¿Cuál concentración NO depende de la temperatura?", options: ["Molaridad", "Molalidad", "Normalidad", "Presión osmótica"], answer: 1, explanation: "La molalidad usa kg de disolvente, no volumen, así que no cambia con T."),
