  QuizQuestion(topic: "disoluciones", question: "¿Qué volumen de disolución 0.50 M contiene 0.25 mol de soluto?", options: ["0.125 L", "0.25 L", "0.50 L", "1.0 L"], answer: 2, explanation: "V = n/M = 0.25 ÷ 0.50 = 0.50 L."),
  QuizQuestion(topic: "disoluciones", question: "Al aforar, el volumen que cuenta es el de:", options: ["El disolvente añadido", "La disolución final", "El soluto", "El matraz vacío"], answer: 1, explanation: "La molaridad usa el volumen final de la disolución aforada."),
  QuizQuestion(topic: "disoluciones", question: "Una disolución 0.10 M de NaCl tiene, por litro, una cantidad de iones Na⁺ de:", options: ["0.05 mol", "0.10 mol", "0.20 mol", "1.0 mol"], answer: 1, explanation: "NaCl → Na⁺ + Cl⁻, proporción 1:1, así que 0.10 mol de Na⁺ por litro."),
  QuizQuestion(topic: "acido-base", question: "El pH de una disolución con [H₃O⁺] = 1.0×10⁻³ M es:", options: ["−3", "3", "7", "11"], answer: 1, explanation: "pH = −log(1.0×10⁻³) = 3."),
  QuizQuestion(topic: "acido-base", question: "Si el pH = 5 a 25 °C, el pOH es:", options: ["5", "7", "9", "14"], answer: 2, explanation: "A 25 °C, pH + pOH = 14.00 → pOH = 14 − 5 = 9."),
  QuizQuestion(topic: "acido-base", question: "El pH de HCl 0.010 M (ácido fuerte) es:", options: ["1", "2", "10", "12"], answer: 1, explanation: "Ácido fuerte: [H₃O⁺] = 0.010 M → pH = −log(0.010) = 2."),
  QuizQuestion(topic: "acido-base", question: "Una reguladora con [A⁻] = [HA] tiene un pH igual a:", options: ["7", "pKa", "pKa + 1", "14 − pKa"], answer: 1, explanation: "Henderson-Hasselbalch: si [A⁻]=[HA], log(1)=0 y pH = pKa."),
  QuizQuestion(topic: "acido-base", question: "Un pH de 3 indica una disolución:", options: ["Básica", "Neutra", "Ácida", "Salina"], answer: 2, explanation: "pH < 7 es ácido a 25 °C."),
  QuizQuestion(topic: "acido-base", question: "Si [H⁺] = 1.0×10⁻⁵ M, el pH es:", options: ["5", "9", "10", "−5"], answer: 0, explanation: "pH = −log(10⁻⁵) = 5."),
  QuizQuestion(topic: "acido-base", question: "El pOH de una disolución con [OH⁻] = 1.0×10⁻² M es:", options: ["2", "12", "10", "0.01"], answer: 0, explanation: "pOH = −log(0.01) = 2; su pH sería 12."),
  QuizQuestion(topic: "acido-base", question: "¿Cuál es un ácido fuerte?", options: ["CH₃COOH", "HCl", "NH₃", "H₂CO₃"], answer: 1, explanation: "HCl se disocia por completo en agua."),
  QuizQuestion(topic: "acido-base", question: "¿Cuál es una base fuerte?", options: ["NaOH", "NH₃", "CH₃COOH", "H₂O"], answer: 0, explanation: "NaOH es una base fuerte: se disocia por completo."),
  QuizQuestion(topic: "acido-base", question: "Al diluir un ácido 10 veces, el pH:", options: ["Baja 1 unidad", "Sube 1 unidad", "No cambia", "Baja 10 unidades"], answer: 1, explanation: "[H⁺] se divide entre 10, así que pH = −log[H⁺] sube 1 unidad."),
  QuizQuestion(topic: "acido-base", question: "Una disolución reguladora resiste cambios de pH porque contiene:", options: ["Solo un ácido fuerte", "Un ácido débil y su base conjugada", "Solo agua", "Un ácido y una base fuertes"], answer: 1, explanation: "El par ácido débil / base conjugada absorbe H⁺ u OH⁻ añadidos."),
  QuizQuestion(topic: "acido-base", question: "El agua pura a 25 °C tiene pH:", options: ["0", "5", "7", "14"], answer: 2, explanation: "[H₃O⁺] = 1.0×10⁻⁷ M → pH = 7."),
  QuizQuestion(topic: "acido-base", question: "En la neutralización HCl + NaOH, el producto principal además de agua es:", options: ["NaCl", "H₂", "Cl₂", "NaH"], answer: 0, explanation: "HCl + NaOH → NaCl + H₂O."),
  QuizQuestion(topic: "acido-base", question: "Si el pH es 11, la disolución es:", options: ["Fuertemente ácida", "Neutra", "Básica", "No se puede saber"], answer: 2, explanation: "pH > 7 es básica a 25 °C."),
  QuizQuestion(topic: "equilibrio", question: "Para A ⇌ B, si Q < K, la reacción neta avanza hacia:", options: ["Reactivos", "Productos", "No avanza: está en equilibrio", "Depende de T"], answer: 1, explanation: "Q < K significa que faltan productos: el sistema avanza hacia productos hasta igualar K."),
  QuizQuestion(topic: "equilibrio", question: "¿Cuál especie NO aparece en la expresión de Kc?", options: ["Un gas", "Un ion en disolución", "Un sólido puro", "Un soluto acuoso"], answer: 2, explanation: "Los sólidos y líquidos puros tienen actividad 1 y se omiten de Kc."),
  QuizQuestion(topic: "equilibrio", question: "Para N₂ + 3 H₂ ⇌ 2 NH₃, al aumentar la presión el equilibrio se desplaza hacia:", options: ["Reactivos (4 mol gas)", "Productos (2 mol gas)", "No se desplaza", "Depende del catalizador"], answer: 1, explanation: "Le Chatelier: más presión → lado con menos moles de gas, los productos (2 frente a 4)."),
  QuizQuestion(topic: "equilibrio", question: "Un catalizador en una reacción en equilibrio:", options: ["Aumenta K", "Desplaza el equilibrio a productos", "Acelera ambos sentidos por igual", "Aumenta el rendimiento final"], answer: 2, explanation: "El catalizador baja Ea en ambos sentidos: se llega antes al equilibrio, pero K no cambia."),
  QuizQuestion(topic: "equilibrio", question: "En el equilibrio, las concentraciones son:", options: ["Iguales entre sí", "Constantes en el tiempo", "Cero", "Iguales a las iniciales"], answer: 1, explanation: "En equilibrio las concentraciones dejan de cambiar, pero no tienen por qué ser iguales."),
  QuizQuestion(topic: "equilibrio", question: "Si K es muy grande, en el equilibrio predominan:", options: ["Los reactivos", "Los productos", "Las dos por igual", "Ninguna especie"], answer: 1, explanation: "K grande significa que la reacción está muy desplazada hacia productos."),
  QuizQuestion(topic: "equilibrio", question: "Al añadir más reactivo a un sistema en equilibrio, este se desplaza hacia:", options: ["Reactivos", "Productos", "No se mueve", "Se detiene"], answer: 1, explanation: "Le Chatelier: el sistema consume el reactivo añadido formando más producto."),
  QuizQuestion(topic: "equilibrio", question: "Para la reacción A(g) ⇌ B(g) + C(g), al disminuir el volumen el equilibrio se desplaza hacia:", options: ["Productos (2 mol gas)", "Reactivos (1 mol gas)", "No se desplaza", "Depende de K"], answer: 1, explanation: "Menos volumen → más presión → lado con menos moles de gas, los reactivos."),
  QuizQuestion(topic: "equilibrio", question: "La tabla ICE sirve para:", options: ["Calcular el pH", "Organizar concentraciones inicial, cambio y equilibrio", "Medir la temperatura", "Ajustar ecuaciones"], answer: 1, explanation: "ICE = Inicial, Cambio, Equilibrio: ordena cualquier cálculo de equilibrio."),
  QuizQuestion(topic: "equilibrio", question: "¿Qué significa Q > K?", options: ["Faltan productos", "Sobra producto: avanza hacia reactivos", "Está en equilibrio", "K es cero"], answer: 1, explanation: "Q > K indica exceso de productos: la reacción neta va hacia reactivos."),
  QuizQuestion(topic: "equilibrio", question: "Al subir la temperatura en una reacción exotérmica, el equilibrio se desplaza hacia:", options: ["Productos", "Reactivos", "No cambia", "El catalizador"], answer: 1, explanation: "En una reacción exotérmica el calor es un producto: subir T desplaza hacia reactivos."),
  QuizQuestion(topic: "equilibrio", question: "Kc para aA + bB ⇌ cC + dD es:", options: ["[A][B]/[C][D]", "[C]ᶜ[D]ᵈ/[A]ᵃ[B]ᵇ", "[A]ᵃ[B]ᵇ/[C]ᶜ[D]ᵈ", "Kc = 1 siempre"], answer: 1, explanation: "Kc = productos elevados a sus coeficientes dividido entre reactivos elevados a los suyos."),
  QuizQuestion(topic: "termo-cinetica", question: "Una reacción con ΔG = −50 kJ/mol es:", options: ["Endotérmica", "Espontánea", "No espontánea", "Está en equilibrio"], answer: 1, explanation: "ΔG < 0 indica proceso espontáneo (exergónico) en esas condiciones."),
  QuizQuestion(topic: "termo-cinetica", question: "La ΔHf° del O₂(g) en condiciones estándar es:", options: ["−249 kJ/mol", "0 kJ/mol", "+249 kJ/mol", "No está definida"], answer: 1, explanation: "Por definición, ΔHf° de un elemento en su forma estándar es 0."),
  QuizQuestion(topic: "termo-cinetica", question: "Si al duplicar [A] la velocidad se cuadruplica (con [B] constante), el orden respecto a A es:", options: ["0", "1", "2", "4"], answer: 2, explanation: "2ᵐ = 4 → m = 2: la velocidad depende de [A]²."),
  QuizQuestion(topic: "termo-cinetica", question: "La vida media de una reacción de primer orden depende de:", options: ["La concentración inicial", "Solo de k", "Del tiempo transcurrido", "De la presión"], answer: 1, explanation: "t½ = ln 2 / k: para primer orden no depende de [A]₀."),
  QuizQuestion(topic: "termo-cinetica", question: "Una reacción con ΔH < 0 es:", options: ["Endotérmica", "Exotérmica", "Espontánea siempre", "Atermica"], answer: 1, explanation: "ΔH negativo significa que libera calor: exotérmica."),
  QuizQuestion(topic: "termo-cinetica", question: "La espontaneidad la decide:", options: ["ΔH solo", "ΔS solo", "ΔG = ΔH − TΔS", "La velocidad"], answer: 2, explanation: "ΔG < 0 → espontánea; ΔG combina entalpía y entropía."),
  QuizQuestion(topic: "termo-cinetica", question: "Si ΔH > 0 y ΔS > 0, la reacción es espontánea a:", options: ["Temperatura baja", "Temperatura alta", "Cualquier temperatura", "Nunca"], answer: 1, explanation: "ΔG = ΔH − TΔS: con T alta, el término −TΔS domina y ΔG se vuelve negativo."),
  QuizQuestion(topic: "termo-cinetica", question: "La energía de activación es:", options: ["La energía liberada", "La barrera mínima para que ocurra la reacción", "La entalpía total", "La velocidad inicial"], answer: 1, explanation: "Ea es la energía mínima que deben superar los reactivos para reaccionar."),
  QuizQuestion(topic: "termo-cinetica", question: "Al subir la temperatura, la velocidad de reacción normalmente:", options: ["Baja", "No cambia", "Aumenta", "Se hace cero"], answer: 2, explanation: "Más T → más moléculas superan Ea y más choques eficaces: k aumenta (Arrhenius)."),
  QuizQuestion(topic: "termo-cinetica", question: "Un catalizador:", options: ["Se consume en la reacción", "Baja la energía de activación", "Cambia ΔH", "Cambia el equilibrio"], answer: 1, explanation: "El catalizador ofrece otro camino con menor Ea, sin consumirse ni cambiar ΔH o K."),
  QuizQuestion(topic: "termo-cinetica", question: "Para una reacción de primer orden, la gráfica de ln[A] frente a t es:", options: ["Una curva", "Una recta con pendiente −k", "Una recta con pendiente +k", "Una parábola"], answer: 1, explanation: "ln[A] = ln[A]₀ − kt: recta de pendiente −k."),
